      "properties": {
        "displayName": "[Preview]: Audit FedRAMP High controls and deploy specific VM Extensions to support audit requirements",
        "policyType": "BuiltIn",
        "description": "This initiative includes audit and VM Extension deployment policies that address a subset of FedRAMP H controls. Additional policies will be added in upcoming releases. For more information, please visit https://aka.ms/fedramph-blueprint.",
